R,C=29,17
g=[[1]*C for _ in range(R)]
pts={ (6,0),(6,1),(6,2),(6,6),(7,7),(8,0),(10,7),(11,0),(11,7),(12,0),(12,7),(13,0),(13,7),(14,7),(16,0),(17,7),(18,0),(20,0),(22,0),(22,1),(22,2),(22,4),(22,7)}
for r,c in pts:g[r][c]=6
for r in range(R):
    cs=[c for c in range(C) if g[r][c]==6]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):g[r][c]=2
for c in range(C):
    rs=[r for r in range(R) if g[r][c]==6]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
